@app.post('/api/docs/{doc_id}/public-link')
async def toggle_public_sharing(
    doc_id: int,
    body: ShareLinkRequest,
    user: User = Depends(get_current_user)
):
    doc = await Document.get_or_none(id=doc_id, owner_id=user.id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")

    doc.is_public = body.enable_public
    doc.share_slug = secrets.token_urlsafe(16) if body.enable_public else None
    await doc.save()
    return {"is_public": doc.is_public, "share_slug": doc.share_slug}
